@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<div class="mb-3">
    <textarea class="form-control" rows="12" @bind="content" @bind:event="oninput"></textarea>
</div>

<div class="d-flex align-items-center gap-3 mb-3">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-outline-danger" @onclick="Clear">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private IJSObjectReference? module;
    private System.Threading.Timer? autoSaveTimer;

    private const string StorageKey = "notepad-content";
    private const string TimestampKey = "notepad-saved-at";

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", Assets["Components/Pages/Notepad.razor.js"]);

            var stored = await module.InvokeAsync<string?>("load", StorageKey);
            if (stored is not null)
            {
                content = stored;
                savedContent = stored;
            }

            var storedTime = await module.InvokeAsync<string?>("load", TimestampKey);
            if (storedTime is not null && DateTime.TryParse(storedTime, out var parsed))
            {
                lastSavedAt = parsed;
            }

            autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSave), null,
                TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));

            StateHasChanged();
        }
    }

    private bool HasUnsavedChanges => content != savedContent;

    private async Task AutoSave()
    {
        if (HasUnsavedChanges)
        {
            await SaveContent();
            StateHasChanged();
        }
    }

    private async Task SaveNow()
    {
        await SaveContent();
    }

    private async Task SaveContent()
    {
        if (module is null) return;

        await module.InvokeVoidAsync("save", StorageKey, content);
        savedContent = content;
        lastSavedAt = DateTime.Now;
        await module.InvokeVoidAsync("save", TimestampKey, lastSavedAt.Value.ToString("o"));
        await module.InvokeVoidAsync("setUnsavedChanges", false);
    }

    private async Task Clear()
    {
        if (module is null) return;

        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;
        await module.InvokeVoidAsync("remove", StorageKey);
        await module.InvokeVoidAsync("remove", TimestampKey);
        await module.InvokeVoidAsync("setUnsavedChanges", false);
    }

    private async Task OnContentChanged()
    {
        if (module is not null && HasUnsavedChanges)
        {
            await module.InvokeVoidAsync("setUnsavedChanges", true);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
        {
            await autoSaveTimer.DisposeAsync();
        }
        if (module is not null)
        {
            await module.InvokeVoidAsync("setUnsavedChanges", false);
            await module.DisposeAsync();
        }
    }
}

let hasUnsavedChanges = false;

function beforeUnloadHandler(e) {
    if (hasUnsavedChanges) {
        e.preventDefault();
    }
}

window.addEventListener("beforeunload", beforeUnloadHandler);

export function save(key, value) {
    localStorage.setItem(key, value);
}

export function load(key) {
    return localStorage.getItem(key);
}

export function remove(key) {
    localStorage.removeItem(key);
}

export function setUnsavedChanges(value) {
    hasUnsavedChanges = value;
}

